import { adminLocation } from './settings-navigation.js';
import { esc, icon, displayName, when, badge, btn, empty, errorBox, field, textInput, checkbox, formEnd, getValue, isChecked, titleCase } from './manage-ui.js';

const tabs = [['users','users','People'],['groups','grid','Groups'],['models','cube','Models'],['usage','chart','Usage & limits'],['audit','clock','Activity'],['system','server','System']];
const generation = [['systemPrompt','System instructions'],['reasoningEffort','Thinking effort'],['temperature','Temperature'],['topP','Top P'],['maxTokens','Output token limit']];
export function createAdmin({ api, state, capabilities, render, modal, close, toast, onIdentityChanged, onCatalogChanged }) {
  const local = { tab: 'users', loading: false, error: '', users: [], groups: [], models: [], events: [], nextCursor: null, hasMore: false, query: '', group: null, members: [], memberCursor: null, usage: [], limits: null, health: null, retention: null, embedding: null, decisions: null, sequence: 0, pending: null };
  const isAdmin = () => state.user?.role === 'admin';
  const tabFromHash = () => tabs.some(t => t[0] === adminLocation(location.hash).section) ? adminLocation(location.hash).section : 'users';
  const userById = id => local.users.find(u => u.id === id);
  const modelById = id => local.models.find(m => m.id === id);
  const groupId = () => adminLocation(location.hash).groupId;
  const gatewayUrl = () => capabilities.adminGatewayUrl || capabilities.gatewayAdminUrl || '';
  function clear() { local.sequence++; Object.assign(local, { users: [], groups: [], models: [], events: [], members: [], usage: [], limits: null, health: null, retention: null, embedding: null, decisions: null, memberCursor: null, group: null, query: '', error: '', loading: false, pending: null }); }
  async function load({ append = false, query = local.query } = {}) {
    if (!isAdmin()) { clear(); return; }
    const sequence = ++local.sequence; local.tab = tabFromHash(); local.loading = true; local.error = ''; local.query = query; render();
    try {
      if (local.tab === 'users') { const r = await api.request(`/api/admin/users${query ? '?q=' + encodeURIComponent(query) : ''}`); if (sequence !== local.sequence) return; local.users = r.users || []; local.hasMore = !!r.hasMore; }
      if (local.tab === 'groups') {
        const id = groupId();
        const r = await api.request(id ? `/api/admin/groups/${encodeURIComponent(id)}` : '/api/admin/groups'); if (sequence !== local.sequence) return;
        if (id) { local.group = r.group; local.members = r.members || []; local.memberCursor = r.nextCursor; const u = await api.request(`/api/admin/users${query ? '?q=' + encodeURIComponent(query) : ''}`); if (sequence !== local.sequence) return; local.users = u.users || []; local.hasMore = !!u.hasMore; }
        else { local.groups = r.groups || []; local.group = null; }
      }
      if (local.tab === 'models') {
        const results = await Promise.all([api.request('/api/admin/models'), api.request('/api/admin/groups')]); if (sequence !== local.sequence) return;
        local.models = results[0].models || []; local.groups = results[1].groups || [];
      }
      if (local.tab === 'usage') { const [u, l] = await Promise.all([api.request(`/api/admin/usage${query ? '?q=' + encodeURIComponent(query) : ''}`), api.request('/api/admin/limits')]); if (sequence !== local.sequence) return; local.usage = u.users || []; local.hasMore = !!u.hasMore; local.limits = l; }
      if (local.tab === 'system') {
        local.retention = null; local.embedding = null; local.health = null; local.decisions = null;
        const [r, e, h, d] = await Promise.all([api.request('/api/admin/retention'), capabilities.features?.knowledge ? api.request('/api/admin/knowledge/embedding').catch(err => ({ error: err.message })) : null, api.request('/api/admin/health').catch(() => null), api.request('/api/admin/decisions').catch(err => ({ error: err.message }))]); if (sequence !== local.sequence) return;
        local.retention = r; local.embedding = e; local.health = h; local.decisions = d;
      }
      if (local.tab === 'audit') { const r = await api.request(`/api/admin/audit?limit=50${append && local.nextCursor ? '&before=' + encodeURIComponent(local.nextCursor) : ''}`); if (sequence !== local.sequence) return; local.events = append ? [...local.events, ...(r.events || [])] : r.events || []; local.nextCursor = r.nextCursor; }
    } catch (e) { if (sequence === local.sequence && e.name !== 'AbortError') local.error = e.message; }
    finally { if (sequence === local.sequence) { local.loading = false; render(); } }
  }
  function shell(content) {
    return `<div class="administration"><div class="settings-section-heading spread"><div><h2>Administration</h2><p>Accounts, model access, and service activity.</p></div>${badge('Administrator', 'accent')}</div><nav class="tabs admin-tabs" aria-label="Administration sections">${tabs.map(([id,glyph,label]) => `<a class="tab ${local.tab === id ? 'active' : ''}" href="#settings/admin/${id}" ${local.tab === id ? 'aria-current="page"' : ''}>${icon(glyph)}${label}</a>`).join('')}</nav>${errorBox(local.error, 'admin-refresh')}${local.loading && !content ? '<div class="management-empty" role="status">Loading administration…</div>' : content}</div>`;
  }
  function people() {
    return `<div class="management-toolbar"><form id="admin-users-search-form" class="management-search"><label class="sr-only" for="admin-users-query">Search accounts</label><input id="admin-users-query" name="query" class="form-control" placeholder="Search name or username…" maxlength="128" value="${esc(local.query)}"><button class="btn small" type="submit">Search</button></form><div class="row">${state.passwords === false ? '' : btn('Invite person', 'admin-invite-user', { icon: 'link', tone: 'small' })}${btn('Create account', 'admin-create-user', { icon: 'plus', tone: 'primary small' })}</div></div>${local.hasMore ? '<p class="inline-note management-note">Showing the first 1,000 matches. Refine the search to find another account.</p>' : ''}${local.users.length ? `<div class="table-wrap"><table class="management-table"><thead><tr><th>Person</th><th>Role</th><th>Status</th><th><span class="sr-only">Actions</span></th></tr></thead><tbody>${local.users.map(u => `<tr><td><div class="account-cell"><span class="avatar">${esc(displayName(u).slice(0,2).toUpperCase())}</span><div><strong>${esc(displayName(u))} ${u.id === state.user.id ? badge('You') : ''}</strong><small>${esc(u.username)}</small></div></div></td><td>${badge(titleCase(u.role), u.role === 'admin' ? 'accent' : '')}</td><td>${badge(u.enabled === false ? 'Disabled' : 'Active', u.enabled === false ? '' : 'accent')}</td><td>${btn('Manage', 'admin-manage-user', { tone: 'small', attrs: `data-id="${esc(u.id)}"` })}</td></tr>`).join('')}</tbody></table></div>` : empty('No accounts found', 'Try another search, or create an account for someone joining your workspace.')}`;
  }
  function groups() {
    if (groupId() && local.group) return groupDetail();
    return `<div class="management-toolbar"><p class="inline-note">Members share projects and collections with their group, and a model can be limited to certain groups. Groups do not grant administrator access.</p>${btn('New group', 'admin-create-group', { icon: 'plus', tone: 'primary small' })}</div>${local.groups.length ? `<div class="table-wrap"><table class="management-table"><thead><tr><th>Group</th><th>Members</th><th><span class="sr-only">Actions</span></th></tr></thead><tbody>${local.groups.map(g => `<tr><td><div class="account-cell"><span class="avatar">${icon('users')}</span><div><strong><a href="#settings/admin/groups/${encodeURIComponent(g.id)}">${esc(g.name)}</a></strong><small>${esc(g.description || 'No description yet.')}</small></div></div></td><td>${Number(g.memberCount || 0)} member${Number(g.memberCount) === 1 ? '' : 's'}</td><td><a class="btn small" href="#settings/admin/groups/${encodeURIComponent(g.id)}">Manage</a></td></tr>`).join('')}</tbody></table></div>` : empty('Start with a group', 'Organize a class, a project team, or a set of people with the same model access.', btn('Create a group', 'admin-create-group', { icon: 'plus', tone: 'primary small' }))}`;
  }
  function groupDetail() {
    const g = local.group, candidates = local.users.filter(u => u.enabled !== false && !local.members.some(m => m.id === u.id));
    return `<a class="back-link" href="#settings/admin/groups">${icon('right')}All groups</a><div class="management-toolbar"><div><h2>${esc(g.name)}</h2><p class="inline-note">${esc(g.description || 'No description yet.')}</p></div><div class="row">${btn('Edit group', 'admin-edit-group', { tone: 'small' })}${btn('Delete', 'admin-delete-group', { tone: 'danger small' })}</div></div><section class="card membership-card"><h3>Add a member</h3><form id="admin-member-search-form" class="management-search"><label class="sr-only" for="admin-member-query">Find an account</label><input id="admin-member-query" name="query" class="form-control" placeholder="Search name or username…" value="${esc(local.query)}"><button class="btn small" type="submit">Search</button></form><form id="admin-add-member-form" class="membership-add">${field('member-user', 'Account', `<select id="member-user" name="member-user" class="form-control" ${candidates.length ? '' : 'disabled'}>${candidates.map(u => `<option value="${esc(u.id)}">${esc(displayName(u))} · ${esc(u.username)}</option>`).join('') || '<option>No matching accounts to add</option>'}</select>`)}<button class="btn small" type="submit" ${candidates.length ? '' : 'disabled'}>Add member</button><div class="form-error" role="alert"></div></form>${local.hasMore ? '<p class="inline-note">Refine your search to find accounts beyond the first 1,000 results.</p>' : ''}</section>${local.members.length ? `<div class="table-wrap"><table class="management-table"><thead><tr><th>Member</th><th>Role</th><th><span class="sr-only">Actions</span></th></tr></thead><tbody>${local.members.map(u => `<tr><td><strong>${esc(displayName(u))}</strong><small>${esc(u.username)}${u.managedOidc ? ' · From single sign-on' : ''}</small></td><td>${esc(titleCase(u.role))}</td><td>${btn('Remove', 'admin-remove-member', { tone: 'small', attrs: `data-id="${esc(u.id)}"` })}</td></tr>`).join('')}</tbody></table></div>` : empty('No members yet', 'Add accounts above to grant the model access configured for this group.')}${local.memberCursor ? `<div class="load-more">${btn('Load more members', 'admin-more-members', { tone: 'small' })}</div>` : ''}`;
  }
  function models() {
    const list = local.models.filter(m => [m.name,m.id,m.description,...(m.tags || [])].join(' ').toLowerCase().includes(local.query.toLowerCase()));
    return `<div class="management-toolbar"><form id="admin-models-search-form" class="management-search"><label class="sr-only" for="admin-model-query">Search models</label><input class="form-control" id="admin-model-query" name="query" placeholder="Search model name, ID, or tags…" value="${esc(local.query)}"><button type="submit" class="btn small">Search</button></form>${gatewayUrl() ? `<a class="btn small" href="${esc(gatewayUrl())}" target="_blank" rel="noopener noreferrer">Manage providers in Gateway${icon('external')}</a>` : ''}</div><p class="inline-note management-note">Publish models, choose the default, and control generation settings. Provider endpoints and credentials are managed in Obleth Gateway.</p>${list.length ? `<div class="table-wrap"><table class="management-table model-table"><thead><tr><th>Model</th><th>Tags</th><th>Visible to</th><th>User controls</th><th>Status</th><th><span class="sr-only">Actions</span></th></tr></thead><tbody>${list.map(m => `<tr><td><strong>${esc(m.name || m.id)}</strong>${m.name && m.name !== m.id ? `<code class="model-id">${esc(m.id)}</code>` : ''}${m.description || m.detail ? `<small>${esc(m.description || m.detail)}</small>` : ''}</td><td><div class="model-tags">${(m.tags || []).map(t => badge(t)).join('') || '<span class="faint">—</span>'}</div></td><td>${m.visibility === 'groups' ? `${m.groupIds?.length || 0} groups` : m.visibility === 'admins' ? 'Administrators' : 'Everyone'}</td><td>${m.allowedOverrides?.length || 0} adjustable</td><td><div class="model-status">${m.isDefault ? badge('Default', 'accent') : ''}${badge(m.available === false ? 'Unavailable' : m.enabled === false ? 'Disabled' : m.published === false ? 'Unpublished' : 'Published', m.available !== false && m.enabled !== false && m.published !== false ? 'accent' : '')}</div></td><td>${btn('Configure', 'admin-edit-model', { tone: 'small', attrs: `data-id="${esc(m.id)}"` })}</td></tr>`).join('')}</tbody></table></div>` : empty('No models found', local.models.length ? 'Try another search.' : 'Register models in Obleth Gateway, then refresh this page.', btn('Refresh models', 'admin-refresh', { icon: 'refresh', tone: 'small' }))}`;
  }
  function usage() {
    const limits = local.limits?.limits || {};
    return `<section class="card site-limits"><div class="spread"><div><h2>Workspace limits</h2><p class="inline-note">Daily allowances reset at 00:00 UTC. Individual overrides can be set below.</p></div>${btn('Edit defaults', 'admin-edit-limits', { icon: 'settings', tone: 'small' })}</div><div class="limit-summary">${[['Daily requests',limits.dailyRequests],['Daily tokens',limits.dailyTokens],['Concurrent responses',limits.concurrentRequests]].map(([name,value]) => `<div><span>${name}</span><strong>${value == null ? 'Unlimited' : Number(value).toLocaleString()}</strong></div>`).join('')}</div></section><div class="management-toolbar"><form id="admin-usage-search-form" class="management-search"><label class="sr-only" for="usage-query">Search usage by account</label><input class="form-control" id="usage-query" name="query" placeholder="Search accounts…" value="${esc(local.query)}"><button class="btn small" type="submit">Search</button></form><p class="inline-note">Today’s usage · UTC</p></div>${local.hasMore ? '<p class="inline-note management-note">Refine the search to find more accounts.</p>' : ''}${local.usage.length ? `<div class="table-wrap"><table class="management-table"><thead><tr><th>Person</th><th>Requests</th><th>Tokens</th><th>30-day errors</th><th><span class="sr-only">Limits</span></th></tr></thead><tbody>${local.usage.map(u => `<tr><td><strong>${esc(displayName(u))}</strong><small>${esc(u.username)}</small></td><td>${Number(u.today?.requests || 0).toLocaleString()}<small>${u.limits?.dailyRequests == null ? 'Unlimited' : '/ ' + Number(u.limits.dailyRequests).toLocaleString()}</small></td><td>${Number(u.today?.totalTokens || 0).toLocaleString()}<small>${u.limits?.dailyTokens == null ? 'Unlimited' : '/ ' + Number(u.limits.dailyTokens).toLocaleString()}</small></td><td>${Number(u.totals?.errors || 0).toLocaleString()}</td><td>${btn('Limits', 'admin-user-limits', { tone: 'small', attrs: `data-id="${esc(u.id)}"` })}</td></tr>`).join('')}</tbody></table></div>` : empty('No matching accounts', 'Try another username or display name.')}`;
  }
  function limitsDialog(userId = null) {
    const limits = userId ? local.limits?.overrides?.find(o => o.userId === userId)?.limits || {} : local.limits?.limits || {};
    const user = local.usage.find(u => u.id === userId);
    modal(userId ? `Limits for ${displayName(user)}` : 'Workspace limits', `<form id="admin-limits-form" data-id="${esc(userId || '')}"><p class="inline-note">${userId ? 'Leave a field blank to inherit the workspace default.' : 'Leave daily limits blank for unlimited usage.'} Concurrent responses must be between 1 and 32.</p>${field('limit-requests', 'Requests per day', textInput('limit-requests', limits.dailyRequests ?? '', 'type="number" min="1" max="1000000" placeholder="' + (userId ? 'Inherit workspace default' : 'Unlimited') + '"'))}${userId ? checkbox('limit-requests-unlimited','Unlimited daily requests', Object.hasOwn(limits,'dailyRequests') && limits.dailyRequests === null) : ''}${field('limit-tokens', 'Tokens per day', textInput('limit-tokens', limits.dailyTokens ?? '', 'type="number" min="1" max="1000000000" placeholder="' + (userId ? 'Inherit workspace default' : 'Unlimited') + '"'))}${userId ? checkbox('limit-tokens-unlimited','Unlimited daily tokens', Object.hasOwn(limits,'dailyTokens') && limits.dailyTokens === null) : ''}${field('limit-concurrent', 'Concurrent responses', textInput('limit-concurrent', limits.concurrentRequests ?? '', `type="number" min="1" max="32" placeholder="Inherit workspace default" ${userId ? '' : 'required'}`))}<p class="inline-note">Token allowances include reported usage and reserved output tokens for active responses.</p>${formEnd('Save limits')}</form>${userId ? `<div class="admin-account-actions">${btn('Remove all overrides', 'admin-remove-limits', { tone: 'small', attrs: `data-id="${esc(userId)}"` })}</div>` : ''}`);
  }
  function audit() {
    return `<div class="management-toolbar"><p class="inline-note">Administrative changes and account security events. Conversation content stays private.</p>${btn('Refresh', 'admin-refresh', { icon: 'refresh', tone: 'small' })}</div>${local.events.length ? `<div class="audit-list">${local.events.map(e => `<article class="audit-event"><span class="audit-dot"></span><div class="grow"><div class="spread"><h3>${esc(titleCase(e.action))}</h3><time>${esc(when(e.createdAt))}</time></div><p>${esc(e.actorName || 'System')} <span>· ${esc(e.targetType || 'account')}${e.targetId ? ' · ' + esc(e.targetId) : ''}</span></p>${e.metadata && Object.keys(e.metadata).length ? `<details><summary>Details</summary><pre>${esc(JSON.stringify(e.metadata, null, 2))}</pre></details>` : ''}</div></article>`).join('')}</div>${local.nextCursor ? `<div class="load-more">${btn(local.loading ? 'Loading…' : 'Load older activity', 'admin-more-audit', { tone: 'small', attrs: local.loading ? 'disabled' : '' })}</div>` : ''}` : empty('No activity yet', 'Account and administration events will appear here.')}`;
  }
  function retentionCard() {
    const r = local.retention;
    if (!r) return '';
    const lastRun = typeof r.lastRun === 'string' ? r.lastRun : r.lastRun?.at;
    return `<section class="setting-card card retention-card"><div class="spread"><h2>Data retention</h2>${badge([r.conversationDays,r.unusedFileDays,r.auditDays].some(v => v != null) ? 'Automatic deletion enabled' : 'Keep forever')}</div><p>Keep all data by default. Enter a number of days to automatically remove eligible data across this installation.</p><form id="admin-retention-form">${field('retention-conversations', 'Inactive conversations · days', textInput('retention-conversations', r.conversationDays ?? '', 'type="number" min="1" max="3650" step="1" placeholder="Keep forever"'), 'Delete conversations with no recent activity, including archived conversations. Active responses are excluded.')}${field('retention-files', 'Unused files · days', textInput('retention-files', r.unusedFileDays ?? '', 'type="number" min="1" max="3650" step="1" placeholder="Keep forever"'), 'Delete older uploads only when no saved conversation references them.')}${field('retention-audit', 'Audit activity · days', textInput('retention-audit', r.auditDays ?? '', 'type="number" min="30" max="3650" step="1" placeholder="Keep forever"'), 'Keep at least 30 days when automatic audit cleanup is enabled.')}<p class="inline-note retention-note">Automatic deletion is permanent and applies to all accounts. Leave fields blank to keep data forever. Backup retention is managed separately.</p>${lastRun ? `<p class="inline-note">Last cleanup: ${esc(when(lastRun))}</p>` : ''}${formEnd('Save retention')}</form></section>`;
  }
  const count = (n, one, many = `${one}s`) => `${n} ${n === 1 ? one : many}`;
  function embeddingCard() {
    const e = local.embedding;
    if (!e) return '';
    if (e.error) return `<section class="setting-card card"><h2>Knowledge search</h2>${errorBox(e.error)}</section>`;
    const i = e.index, current = e.effective.model, models = [...new Set([...(e.models || []), current, e.defaults.model])].sort();
    const status = i.pendingDocuments || i.pendingSavedItems
      ? `Indexing again: ${count(i.pendingDocuments, 'document')} of ${i.documents} and ${count(i.pendingSavedItems, 'saved item')} of ${i.savedItems} still to do. Until then, search finds only what is done.`
      : `${count(i.documents, 'document')} and ${count(i.savedItems, 'saved item')} are indexed with ${current}.`;
    const option = id => `<option value="${esc(id)}" ${id === current ? 'selected' : ''}>${esc(id)}${id === e.defaults.model ? ' (default)' : ''}</option>`;
    const prefix = (id, label, value, help) => field(id, label, `<textarea class="form-control" id="${id}" name="${id}" rows="2" maxlength="500" spellcheck="false">${esc(value)}</textarea>`, help);
    return `<section class="setting-card card embedding-card"><div class="spread"><h2>Knowledge search</h2>${badge(i.pendingDocuments || i.pendingSavedItems ? 'Indexing' : 'Up to date')}</div><p>Chat turns documents and saved items into vectors with an embedding model, so search can find passages by meaning.</p><p class="inline-note">${esc(status)}</p><form id="admin-embedding-form">${field('embedding-model', 'Embedding model', `<select class="form-control" id="embedding-model" name="embedding-model" data-previous="${esc(current)}">${models.map(option).join('')}</select>`, e.models ? 'Embedding models your gateway offers.' : 'The gateway could not list its embedding models, so only the current and default models are shown.')}${prefix('embedding-query', 'Search prefix', e.effective.queryPrefix, 'Put before each search. Chat fills in the prefix the model’s makers publish; change it only if the model’s documentation says otherwise.')}${prefix('embedding-document', 'Passage prefix', e.effective.documentPrefix, 'Put before each passage and saved item. Many models use none.')}<p class="inline-note retention-note">Changing the model or a prefix makes Chat index every document and saved item again: vectors from different models can’t be compared. Until that finishes, search finds only what has been redone, and a large library takes a while and uses the gateway’s embedding capacity.</p><div class="form-error" role="alert"></div><div class="modal-actions">${btn('Use defaults', 'admin-embedding-defaults', { tone: 'small' })}<button class="btn primary" type="submit">Save</button></div></form></section>`;
  }
  const decisionsUsage = endpoint => ({ gateway: 'Questions go to the gateway as the person they are for, so they count toward that person’s usage and limits.', custom: 'Questions go with this endpoint’s key, so their usage counts against the key, not against people.', off: 'Nothing is asked. Features that use decisions run without them.' })[endpoint] || '';
  function decisionsCard() {
    const d = local.decisions;
    if (!d) return '';
    if (d.error) return `<section class="setting-card card"><h2>Decisions</h2>${errorBox(d.error)}</section>`;
    const option = ([id, label]) => `<option value="${id}" ${id === d.endpoint ? 'selected' : ''}>${label}</option>`;
    const keyHelp = d.keyUnreadable ? 'The saved key can’t be read because the installation’s secret key changed. Enter it again.' : d.hasKey ? 'A key is saved. Leave this blank to keep it.' : d.canStoreKey ? 'Sent as a bearer token. Leave blank if the endpoint needs none.' : 'Saving a key needs OBLETH_CHAT_SECRET_KEY_FILE, which encrypts it.';
    const endpoint = field('decisions-endpoint', 'Ask', `<select class="form-control" id="decisions-endpoint" name="decisions-endpoint">${[['gateway', 'This gateway'], ['custom', 'Another endpoint'], ['off', 'Off']].map(option).join('')}</select>`, decisionsUsage(d.endpoint));
    const custom = `<div class="decisions-custom" ${d.endpoint === 'custom' ? '' : 'hidden'}>${field('decisions-url', 'Endpoint URL', textInput('decisions-url', d.url || '', 'type="url" maxlength="2048" placeholder="https://decisions.example.com" spellcheck="false" autocomplete="off"'), 'An address that takes POST requests in the verdicts format. An address with no path, or one ending in /v1, gets /v1/verdicts added.')}${field('decisions-key', 'Key', textInput('decisions-key', '', `type="password" maxlength="4096" autocomplete="off" ${d.canStoreKey ? '' : 'disabled'} placeholder="${d.hasKey && !d.keyUnreadable ? 'Saved key kept' : ''}"`), keyHelp)}${d.hasKey ? checkbox('decisions-remove-key', 'Remove the saved key') : ''}</div>`;
    const model = field('decisions-model', 'Model', `${textInput('decisions-model', d.model || '', 'maxlength="160" list="decisions-models" placeholder="The endpoint’s default" spellcheck="false" autocomplete="off"')}<datalist id="decisions-models">${(d.models || []).map(id => `<option value="${esc(id)}"></option>`).join('')}</datalist>`, 'Leave blank to let the endpoint choose. The model must return token probabilities (logprobs): most self-hosted servers do, and many hosted APIs don’t.');
    return `<section class="setting-card card decisions-card"><div class="spread"><h2>Decisions</h2>${badge(d.endpoint === 'off' ? 'Off' : 'On')}</div><p>Short yes/no and pick-one questions Chat asks a model, such as whether a research run really tested its idea. Chat asks them in the verdicts format, so your gateway or any service that speaks it can answer. When decisions are off or fail, work goes on without them.</p><form id="admin-decisions-form">${endpoint}${custom}${model}${checkbox('decisions-check-runs', 'Check research runs', d.checkRuns, 'When a run finishes, ask whether it really tested its idea, and tell the chat when it may not have. The result shows on the project’s Research tab.')}<p class="inline-note decisions-result" aria-live="polite"></p><div class="form-error" role="alert"></div><div class="modal-actions">${btn('Check', 'admin-decisions-check', { tone: 'small' })}<button class="btn primary" type="submit">Save</button></div></form></section>`;
  }
  // The form as a settings change. The URL and key count only for another endpoint, and a
  // blank key keeps the saved one.
  function decisionsBody(form) {
    const body = { endpoint: getValue(form, 'decisions-endpoint'), model: getValue(form, 'decisions-model').trim() || null, checkRuns: isChecked(form, 'decisions-check-runs') };
    if (body.endpoint !== 'custom') return body;
    const url = getValue(form, 'decisions-url').trim(), key = getValue(form, 'decisions-key').trim();
    if (url) body.url = url;
    if (key) body.key = key; else if (isChecked(form, 'decisions-remove-key')) body.key = null;
    return body;
  }
  // Everything else about the installation is set where Chat runs, so the tab points there.
  // Whether this replica runs workspaces, and if not, why.
  function workspaceStatus() {
    const w = local.health?.workspaces;
    if (!w) return 'Linux workspaces and each person’s browser on Kubernetes';
    if (w.enabled) return esc(`On, in namespace ${w.namespace}${w.browser ? ', with the browser' : ''}`);
    return esc(`Off: ${w.off || 'not set up'}`);
  }
  function system() {
    const docs = 'https://www.obleth.com/docs/run-chat', link = ([glyph, label, path, note]) => `<a class="setting-line docs-link" href="${docs}${path}" target="_blank" rel="noopener">${icon(glyph)}<div class="grow"><h3>${label}</h3><p>${note}</p></div>${icon('external')}</a>`;
    const pages = [['cube', 'Connect the gateway', '/connect-gateway', 'Model access and inference through Obleth'], ['lock', 'Accounts and sign-in', '/accounts', 'Local accounts and single sign-on'], ['book', 'Knowledge', '/enable-knowledge', 'Collections and saved items in S3'], ['terminal', 'Workspaces and the browser', '/enable-workspaces', workspaceStatus()], ['link', 'Connections and clusters', '/enable-connections', 'MCP servers, Slurm and Kubernetes'], ['shield', 'Reverse proxies', '/reverse-proxies', 'Client addresses and sign-in limits'], ['chart', 'Operate Chat', '/operations', 'Health checks, metrics and backups'], ['settings', 'Environment variables', '/environment-variables', 'Every setting in one list']];
    return `<div class="admin-system-grid">${retentionCard()}${embeddingCard()}${decisionsCard()}<section class="setting-card card"><h2>Set where Chat runs</h2><p>The rest is configured with environment variables when Chat is deployed. These guides show how.</p>${pages.map(link).join('')}</section></div>`;
  }

  function view() {
    if (!isAdmin()) return `<div class="settings-access-denied">${empty('Administrator access required', 'Your personal account settings are available below.', '<a class="btn" href="#settings">Open Settings</a>')}</div>`;
    local.tab = tabFromHash();
    return shell(local.loading && !({ users: local.users.length, groups: local.groups.length || local.group, models: local.models.length, audit: local.events.length, usage: local.limits, system: true }[local.tab]) ? '' : ({ users: people, groups, models, audit, usage, system }[local.tab])());
  }
  // Any change to what makes the vectors re-indexes everything, so it is confirmed first.
  async function saveEmbedding(body, next) {
    const e = local.embedding, now = e.effective;
    const save = async () => { const r = await api.request('/api/admin/knowledge/embedding', { method: 'PATCH', body }); local.embedding = r; close(); render(); toast(r.reindexed ? 'Saved. Knowledge is being indexed again.' : 'Saved'); };
    if (next.model === now.model && next.queryPrefix === now.queryPrefix && next.documentPrefix === now.documentPrefix) { await save(); return; }
    const i = e.index;
    confirm('Index everything again?', `Chat will index all ${count(i.documents, 'document')} and ${count(i.savedItems, 'saved item')} again with ${next.model}. Vectors from the old and new settings can't be compared, so until it finishes, people's searches find only what has been redone. This can't be undone by switching back: that indexes everything again too.`, 'Change and re-index', save);
  }
  function confirm(title, text, label, callback) { local.pending = callback; modal(title, `<p>${esc(text)}</p><div class="modal-actions">${btn('Cancel', 'close')}${btn(label, 'admin-confirm', { tone: 'danger' })}</div>`); }
  function accountDialog(invite = false) {
    modal(invite ? 'Invite a person' : 'Create an account', `<form id="${invite ? 'admin-invite-form' : 'admin-create-user-form'}">${field('account-username', 'Username', textInput('account-username', '', 'maxlength="128" autocomplete="off" required'))}${field('account-name', 'Display name', textInput('account-name', '', 'maxlength="128" required'))}${field('account-role', 'Role', '<select class="form-control" name="account-role" id="account-role"><option value="user">User</option><option value="admin">Administrator</option></select>', 'Administrators manage accounts and model access.')}${invite ? '<p class="inline-note">A one-time link lets this person choose their password. You can copy it after creating the account.</p>' : state.passwords === false ? '<p class="inline-note">Passwords are off. Link the account to single sign-on after creating it.</p>' : `${field('account-password', 'Initial password', textInput('account-password', '', 'type="password" minlength="12" autocomplete="new-password" required'))}${checkbox('account-force-change', 'Require a password change at first sign-in', true)}`}${formEnd(invite ? 'Create invitation' : 'Create account')}</form>`);
  }
  function accessLink(result) {
    modal(result.kind === 'invite' ? 'Invitation ready' : 'Password reset link ready', `<p>Share this link privately. It can be used once and expires ${esc(when(result.expiresAt))}.</p>${field('one-time-link', 'One-time link', `<textarea class="form-control" id="one-time-link" rows="3" readonly>${esc(result.url)}</textarea>`)}<div class="modal-actions">${btn('Done', 'close')}${btn('Copy link', 'admin-copy-link', { icon: 'copy', tone: 'primary' })}</div>`);
  }
  function manageUser(u) {
    modal(`Manage ${displayName(u)}`, `<form id="admin-edit-user-form" data-id="${esc(u.id)}">${field('managed-name', 'Display name', textInput('managed-name', displayName(u), 'maxlength="100" required'))}${field('managed-role', 'Role', `<select class="form-control" id="managed-role" name="managed-role"><option value="user" ${u.role === 'user' ? 'selected' : ''}>User</option><option value="admin" ${u.role === 'admin' ? 'selected' : ''}>Administrator</option></select>`)}<div class="detail-row"><span>Username</span><span>${esc(u.username)}</span></div><div class="detail-row"><span>Access</span><span>${u.enabled === false ? 'Disabled' : 'Active'}</span></div>${formEnd()}</form><div class="admin-account-actions"><h3>Account security</h3><div class="user-actions">${state.passwords === false ? '' : `${btn('Reset password', 'admin-reset-password', { tone: 'small', attrs: `data-id="${esc(u.id)}"` })}${btn('Create reset link', 'admin-reset-link', { tone: 'small', attrs: `data-id="${esc(u.id)}"` })}`}${state.oidc ? btn('Link single sign-on', 'admin-link-oidc', { tone: 'small', attrs: `data-id="${esc(u.id)}"` }) : ''}${btn('Revoke sessions', 'admin-revoke-sessions', { tone: 'small', attrs: `data-id="${esc(u.id)}"` })}${btn(u.enabled === false ? 'Enable account' : 'Disable account', 'admin-toggle-user', { tone: u.enabled === false ? 'small' : 'danger small', attrs: `data-id="${esc(u.id)}"` })}</div></div>`);
  }
  function groupDialog(g = null) { modal(g ? 'Edit group' : 'Create group', `<form id="admin-group-form" data-id="${esc(g?.id || '')}">${field('group-name', 'Group name', textInput('group-name', g?.name || '', 'maxlength="100" required'))}${field('group-description', 'Description', `<textarea id="group-description" name="group-description" class="form-control" maxlength="1000" rows="3">${esc(g?.description || '')}</textarea>`)}${formEnd(g ? 'Save group' : 'Create group')}</form>`); }
  function editModel(m) {
    const d = m.defaults || {};
    modal(`Configure ${m.name || m.id}`, `<form id="admin-model-form" data-id="${esc(m.id)}"><p class="inline-note model-id">${esc(m.id)}</p>${field('model-name', 'Display name', textInput('model-name', m.name || m.id, 'maxlength="128" required'))}${field('model-description', 'Description', `<textarea class="form-control" id="model-description" name="model-description" maxlength="2048" rows="2">${esc(m.description || '')}</textarea>`)}<div class="form-columns">${field('model-tags', 'Tags', textInput('model-tags', (m.tags || []).join(', '), 'maxlength="512"'), 'Separate tags with commas.')}${field('model-order', 'Sort order', textInput('model-order', m.order || 0, 'type="number" step="1" min="-10000" max="10000" required'))}</div>${checkbox('model-enabled', 'Enabled', m.enabled !== false, 'Allow requests to this model.')}${checkbox('model-published', 'Published', m.published !== false, 'Show this model in the account catalog.')}${checkbox('model-default', 'Default model', !!m.isDefault, 'Auto routes to this model when the account can access it.')}${checkbox('model-worker', 'Worker', !!m.worker, 'Other models can hand tasks to this one, several at once, to explore a workspace and report back. Choose fast, efficient models.')}${field('model-visibility', 'Visible to', `<select id="model-visibility" name="model-visibility" class="form-control"><option value="all" ${m.visibility === 'all' ? 'selected' : ''}>Everyone</option><option value="admins" ${m.visibility === 'admins' ? 'selected' : ''}>Administrators</option><option value="groups" ${m.visibility === 'groups' ? 'selected' : ''}>Selected groups</option></select>`)}<div class="model-visibility-groups" ${m.visibility === 'groups' ? '' : 'hidden'}><p class="inline-note">Choose the groups that can use this model.</p>${local.groups.map(g => checkbox(`model-group-${g.id}`, g.name, (m.groupIds || []).includes(g.id))).join('') || '<p class="inline-note">Create a group before selecting group-only access.</p>'}</div><div class="form-section-heading"><h3>Generation defaults</h3><p class="inline-note">Uncheck a control to lock it to the model default.</p></div>${field('model-systemPrompt', 'System instructions', `<textarea class="form-control" name="model-systemPrompt" id="model-systemPrompt" rows="3" maxlength="8192">${esc(d.systemPrompt || '')}</textarea>`)}<div class="form-columns">${field('model-reasoningEffort', 'Thinking effort', `<select class="form-control" id="model-reasoningEffort" name="model-reasoningEffort">${['none','low','medium','high'].map(v => `<option ${d.reasoningEffort === v ? 'selected' : ''}>${v}</option>`).join('')}</select>`)}${field('model-temperature', 'Temperature', textInput('model-temperature', d.temperature ?? .7, 'type="number" min="0" max="2" step="0.1" required'))}${field('model-topP', 'Top P', textInput('model-topP', d.topP ?? 1, 'type="number" min="0.01" max="1" step="0.01" required'))}${field('model-maxTokens', 'Output token limit', textInput('model-maxTokens', d.maxTokens || '', 'type="number" min="0" max="262144" placeholder="The model’s own limit"'))}</div><div class="override-list">${generation.map(([key,label]) => checkbox(`allow-${key}`, `Users may change ${label.toLowerCase()}`, (m.allowedOverrides || []).includes(key))).join('')}</div>${formEnd('Save model policy')}</form>`);
  }
  const actions = {
    'admin-refresh': () => load(), 'admin-edit-limits': () => limitsDialog(), 'admin-user-limits': el => limitsDialog(el.dataset.id),
    'admin-remove-limits': async el => { await api.request(`/api/admin/limits/${encodeURIComponent(el.dataset.id)}`, { method: 'DELETE' }); close(); await load(); toast('Account uses workspace limits'); }, 'admin-more-audit': () => load({ append: true }),
    'admin-create-user': () => accountDialog(), 'admin-invite-user': () => accountDialog(true),
    'admin-manage-user': el => manageUser(userById(el.dataset.id)),
    'admin-embedding-defaults': async () => { const d = local.embedding?.defaults; if (d) await saveEmbedding({ model: null, queryPrefix: null, documentPrefix: null }, d); },
    'admin-decisions-check': async el => {
      const form = el.closest('form'), out = form.querySelector('.decisions-result');
      out.textContent = 'Asking…';
      try {
        const r = await api.request('/api/admin/decisions/check', { method: 'POST', body: decisionsBody(form) }), who = r.model || 'The endpoint', yes = Math.round((r.yes || 0) * 100);
        out.textContent = !r.ok ? `No answer: ${r.error}` : r.yes >= 0.5 ? `Working. ${who} answered a sample true statement correctly (${yes}% yes) in ${r.ms} ms.` : `${who} answered a sample true statement wrongly (${yes}% yes). Try another model.`;
      } catch (e) { out.textContent = `No answer: ${e.message}`; }
    },
    'admin-confirm': async () => { const action = local.pending; local.pending = null; if (action) await action(); },
    'admin-copy-link': async () => { const value = document.querySelector('#one-time-link').value; try { await navigator.clipboard.writeText(value); toast('One-time link copied'); } catch { document.querySelector('#one-time-link').select(); toast('Select and copy this link'); } },
    'admin-toggle-user': el => { const u = userById(el.dataset.id), enabled = u.enabled === false; confirm(enabled ? 'Enable this account?' : 'Disable this account?', enabled ? 'This person will be able to sign in again.' : 'This person will be signed out and unable to sign in until the account is enabled again.', enabled ? 'Enable account' : 'Disable account', async () => { await api.request(`/api/admin/users/${encodeURIComponent(u.id)}`, { method: 'PATCH', body: { enabled } }); close(); if (u.id === state.user.id) await onIdentityChanged(); else await load(); toast(enabled ? 'Account enabled' : 'Account disabled'); }); },
    'admin-revoke-sessions': el => confirm('Sign out this person?', 'All their active sessions will be revoked. They can sign in again with their password or single sign-on.', 'Revoke sessions', async () => { await api.request(`/api/admin/users/${encodeURIComponent(el.dataset.id)}/revoke-sessions`, { method: 'POST' }); close(); toast('Sessions revoked'); }),
    'admin-reset-link': async el => accessLink(await api.request(`/api/admin/users/${encodeURIComponent(el.dataset.id)}/access-link`, { method: 'POST', body: { kind: 'reset', expiresInHours: 24 } })),
    'admin-reset-password': el => modal('Set a temporary password', `<form id="admin-reset-password-form" data-id="${esc(el.dataset.id)}">${field('temporary-password', 'New password', textInput('temporary-password', '', 'type="password" minlength="12" autocomplete="new-password" required'))}${checkbox('temporary-force-change', 'Require a password change at next sign-in', true)}<p class="inline-note">Existing sessions will be signed out.</p>${formEnd('Reset password')}</form>`),
    'admin-link-oidc': el => modal('Link single sign-on', `<form id="admin-link-oidc-form" data-id="${esc(el.dataset.id)}"><p class="inline-note">Use the exact, verified subject identifier for this person from your configured identity provider.</p>${field('oidc-subject', 'Provider subject identifier', textInput('oidc-subject', '', 'maxlength="1024" autocomplete="off" required'))}${formEnd('Link identity')}</form>`),
    'admin-more-members': async () => { const id = groupId(), sequence = local.sequence; if (!local.memberCursor) return; const r = await api.request(`/api/admin/groups/${encodeURIComponent(id)}?after=${encodeURIComponent(local.memberCursor)}`); if (sequence !== local.sequence || id !== groupId()) return; local.members = [...local.members, ...(r.members || []).filter(m => !local.members.some(old => old.id === m.id))]; local.memberCursor = r.nextCursor; render(); },
    'admin-create-group': () => groupDialog(), 'admin-edit-group': () => groupDialog(local.group),
    'admin-delete-group': () => confirm('Delete this group?', 'Memberships will be removed. Models restricted to this group may become inaccessible to its members.', 'Delete group', async () => { await api.request(`/api/admin/groups/${encodeURIComponent(local.group.id)}`, { method: 'DELETE' }); close(); location.hash = 'settings/admin/groups'; toast('Group deleted'); }),
    'admin-remove-member': el => confirm('Remove this member?', 'This person will lose access granted through this group.', 'Remove member', async () => { await api.request(`/api/admin/groups/${encodeURIComponent(local.group.id)}/members/${encodeURIComponent(el.dataset.id)}`, { method: 'DELETE' }); close(); await load(); toast('Member removed'); }),
    'admin-edit-model': el => editModel(modelById(el.dataset.id)),
  };
  async function submit(form) {
    if (form.id === 'admin-users-search-form' || form.id === 'admin-member-search-form' || form.id === 'admin-usage-search-form') { await load({ query: getValue(form, 'query').trim() }); return; }
    if (form.id === 'admin-models-search-form') { local.query = getValue(form, 'query').trim(); render(); return; }
    if (form.id === 'admin-embedding-form') {
      const e = local.embedding, d = e.defaults;
      // A value equal to the default follows the default: the environment's model, and
      // the chosen model's own prefixes.
      const pick = (value, fallback) => value === fallback ? null : value;
      const next = { model: getValue(form, 'embedding-model'), queryPrefix: getValue(form, 'embedding-query').replace(/\r\n/g, '\n'), documentPrefix: getValue(form, 'embedding-document').replace(/\r\n/g, '\n') };
      const own = e.prefixes?.[next.model] || { queryPrefix: '', documentPrefix: '' };
      await saveEmbedding({ model: pick(next.model, d.model), queryPrefix: pick(next.queryPrefix, own.queryPrefix), documentPrefix: pick(next.documentPrefix, own.documentPrefix) }, next);
      return;
    }
    if (form.id === 'admin-decisions-form') { local.decisions = await api.request('/api/admin/decisions', { method: 'PATCH', body: decisionsBody(form) }); render(); toast('Decisions saved'); return; }
    if (form.id === 'admin-retention-form') {
      const body = Object.fromEntries([['conversationDays','retention-conversations'],['unusedFileDays','retention-files'],['auditDays','retention-audit']].map(([key,id]) => [key,getValue(form,id).trim() ? Number(getValue(form,id)) : null]));
      const save = async () => { const r = await api.request('/api/admin/retention', { method: 'PATCH', body }); local.retention = r; close(); render(); toast('Retention policy saved'); };
      if (Object.values(body).some(v => v != null)) {
        const summary = [['Inactive conversations',body.conversationDays],['Unused files',body.unusedFileDays],['Audit activity',body.auditDays]].map(([label,days]) => `${label}: ${days == null ? 'keep forever' : `delete after ${days} days`}`).join('. ');
        confirm('Enable automatic deletion?', `${summary}. This applies to all accounts and permanently deletes eligible data during scheduled cleanup. Backup retention is managed separately.`, 'Apply deletion policy', save);
      } else await save();
      return;
    }
    if (form.id === 'admin-limits-form') {
      const id = form.dataset.id, body = {};
      for (const [name,key] of [['requests','dailyRequests'],['tokens','dailyTokens'],['concurrent','concurrentRequests']]) { const value = getValue(form, `limit-${name}`); if (id && name !== 'concurrent' && isChecked(form, `limit-${name}-unlimited`)) body[key] = null; else if (value) body[key] = Number(value); else if (!id && name !== 'concurrent') body[key] = null; }
      await api.request(`/api/admin/limits${id ? '/' + encodeURIComponent(id) : ''}`, { method: id ? 'PUT' : 'PATCH', body }); close(); await load(); toast('Usage limits saved');
    }
    if (form.id === 'admin-create-user-form' || form.id === 'admin-invite-form') {
      const invite = form.id === 'admin-invite-form';
      const body = { username: getValue(form, 'account-username').trim(), displayName: getValue(form, 'account-name').trim(), role: getValue(form, 'account-role') };
      if (!invite && state.passwords !== false) { body.password = getValue(form, 'account-password'); body.forcePasswordChange = isChecked(form, 'account-force-change'); }
      const r = await api.request(invite ? '/api/admin/invitations' : '/api/admin/users', { method: 'POST', body }); await load(); if (invite) accessLink(r); else { close(); toast('Account created'); }
    }
    if (form.id === 'admin-edit-user-form') {
      const u = userById(form.dataset.id), body = { displayName: getValue(form, 'managed-name').trim(), role: getValue(form, 'managed-role') };
      const save = async () => { await api.request(`/api/admin/users/${encodeURIComponent(u.id)}`, { method: 'PATCH', body }); close(); if (u.id === state.user.id) await onIdentityChanged(); else await load(); toast('Account updated'); };
      if (body.role !== u.role) confirm('Change this account’s role?', body.role === 'admin' ? 'This person will be able to manage users, groups, model access, and installation settings.' : 'This person will lose administrator access. Their personal conversations will stay private and available.', 'Change role', save); else await save();
    }
    if (form.id === 'admin-link-oidc-form') { await api.request('/api/admin/oidc-identities', { method: 'POST', body: { userId: form.dataset.id, subject: getValue(form, 'oidc-subject').trim() } }); close(); toast('Single sign-on identity linked'); }
    if (form.id === 'admin-reset-password-form') { await api.request(`/api/admin/users/${encodeURIComponent(form.dataset.id)}/password`, { method: 'POST', body: { newPassword: getValue(form, 'temporary-password'), forcePasswordChange: isChecked(form, 'temporary-force-change') } }); close(); toast('Password reset; existing sessions signed out'); }
    if (form.id === 'admin-group-form') { const id = form.dataset.id; await api.request(`/api/admin/groups${id ? '/' + encodeURIComponent(id) : ''}`, { method: id ? 'PATCH' : 'POST', body: { name: getValue(form, 'group-name').trim(), description: getValue(form, 'group-description').trim() } }); close(); await load(); toast(id ? 'Group updated' : 'Group created'); }
    if (form.id === 'admin-add-member-form') { const id = getValue(form, 'member-user'); if (!id) return; await api.request(`/api/admin/groups/${encodeURIComponent(local.group.id)}/members/${encodeURIComponent(id)}`, { method: 'PUT' }); await load(); toast('Member added'); }
    if (form.id === 'admin-model-form') {
      const body = { name: getValue(form, 'model-name').trim(), description: getValue(form, 'model-description').trim(), tags: [...new Set(getValue(form, 'model-tags').split(',').map(t => t.trim()).filter(Boolean))], order: Number(getValue(form, 'model-order')), enabled: isChecked(form, 'model-enabled'), published: isChecked(form, 'model-published'), isDefault: isChecked(form, 'model-default'), worker: isChecked(form, 'model-worker'), visibility: getValue(form, 'model-visibility'), groupIds: local.groups.filter(g => isChecked(form, `model-group-${g.id}`)).map(g => g.id), defaults: { systemPrompt: getValue(form, 'model-systemPrompt'), reasoningEffort: getValue(form, 'model-reasoningEffort'), temperature: Number(getValue(form, 'model-temperature')), topP: Number(getValue(form, 'model-topP')), maxTokens: Number(getValue(form, 'model-maxTokens')) }, allowedOverrides: generation.filter(([key]) => isChecked(form, `allow-${key}`)).map(([key]) => key) };
      await api.request(`/api/admin/models/${encodeURIComponent(form.dataset.id)}`, { method: 'PUT', body }); const catalog = await api.request('/api/models'); state.models = catalog.models || []; onCatalogChanged?.(); close(); await load(); toast('Model policy saved');
    }
  }
  // A new model brings its own prefixes, unless the ones shown were changed by hand.
  function modelPrefixes(select) {
    const prefixes = local.embedding?.prefixes || {}, before = prefixes[select.dataset.previous] || {}, after = prefixes[select.value] || { queryPrefix: '', documentPrefix: '' };
    for (const [id, key] of [['embedding-query', 'queryPrefix'], ['embedding-document', 'documentPrefix']]) {
      const box = select.form?.elements.namedItem(id);
      if (box && box.value.replace(/\r\n/g, '\n') === (before[key] ?? '')) box.value = after[key];
    }
    select.dataset.previous = select.value;
  }
  function input(event) {
    if (event.target.id === 'model-visibility') document.querySelector('.model-visibility-groups').hidden = event.target.value !== 'groups';
    if (event.target.id === 'embedding-model') modelPrefixes(event.target);
    if (event.target.id === 'decisions-endpoint') {
      const form = event.target.form;
      form.querySelector('.decisions-custom').hidden = event.target.value !== 'custom';
      event.target.closest('.management-field').querySelector('.field-help').textContent = decisionsUsage(event.target.value);
    }
  }
  return { view, load, clear, actions, submit, input };
}
